#!/usr/bin/env bash
# ════════════════════════════════════════════════════════════════════
#  VORTEXNET / ورتکس‌نت — FRESH INSTALL / UPDATE (self-contained, one command)
#
#  چه کار می‌کند:
#   • حساب کاربری مشتری (نام کاربری یکتا + رمز)
#   • پرداخت راحت: کارت‌به‌کارت + فقط ۴ رقم آخر کارت
#   • «سفارشات» و «سرویس من» زنده (حجم/روز باقی‌مانده از پاسارگارد)
#   • چت پشتیبانی داخل سایت ↔ پنل ادمین
#   • ساخت خودکار کانفیگ ۳۰روزه در پاسارگارد بعد از تأیید پرداخت
#   • رفع به‌هم‌ریختگی شماره کارت و ایرادهای موبایل
#
#  رمز پنل و کلید API پاسارگارد در این فایل نیست؛ روی سرور خودت
#  در server/data ذخیره شده‌اند و دست نخورده می‌مانند.
#
#  Usage (on YOUR server):
#    [VORTEXNET_DIR=/opt/vortexnet] [API_PORT=9273] [DOMAIN=example.com] \
#    [SSL_EMAIL=you@mail.com|none] bash vortexnet-setup.sh
#
#    Moving servers with existing users/orders/settings:
#      VORTEXNET_DATA_ARCHIVE=/root/vortexnet-data.tar.gz ... bash vortexnet-setup.sh
#
#    NORKHIZ_ONLY_FILES=1 VORTEXNET_DIR=/tmp/test bash vortexnet-setup.sh
#      → dry run: only extracts files (used by the author to verify).
# ════════════════════════════════════════════════════════════════════
set -euo pipefail
export DEBIAN_FRONTEND=noninteractive

c_reset=$'\033[0m'; c_gold=$'\033[38;5;179m'; c_cyan=$'\033[38;5;81m'; c_red=$'\033[38;5;203m'; c_dim=$'\033[2m'
log()  { printf "%s▸%s %s\n" "$c_cyan" "$c_reset" "$*"; }
ok()   { printf "%s✓%s %s\n" "$c_gold" "$c_reset" "$*"; }
warn() { printf "%s!%s %s\n" "$c_gold" "$c_reset" "$*"; }
die()  { printf "%s✗ %s%s\n" "$c_red" "$*" "$c_reset" >&2; exit 1; }

SUDO=""; [[ "${EUID:-$(id -u)}" -ne 0 ]] && SUDO="sudo"
API_PORT="${API_PORT:-9273}"
DOMAIN="${DOMAIN:-}"
SSL_EMAIL="${SSL_EMAIL:-}"

# ── locate the existing site clone ──────────────────────────────────
find_dir() {
  if [[ -n "${VORTEXNET_DIR:-}" ]]; then echo "$VORTEXNET_DIR"; return; fi
  if [[ -n "${NORKHIZ_DIR:-}" ]]; then echo "$NORKHIZ_DIR"; return; fi
  local cand
  for cand in "$PWD" /root/1387eiman/1387eiman /root/1387eiman "$HOME/1387eiman/1387eiman" "$HOME/1387eiman" /opt/1387eiman; do
    if [[ -f "$cand/package.json" && -f "$cand/vite.config.js" && -f "$cand/install.sh" ]]; then echo "$cand"; return; fi
  done
}
APP_DIR="$(find_dir || true)"
if [[ -z "${APP_DIR:-}" ]]; then
  APP_DIR="$(find /root "$HOME" /opt /srv -maxdepth 4 -name package.json -path '*1387eiman*' 2>/dev/null | head -1 | xargs -r dirname || true)"
fi
if [[ -z "${APP_DIR:-}" ]]; then
  APP_DIR="${VORTEXNET_DIR:-/opt/vortexnet}"
  log "No existing site found — fresh install into ${APP_DIR}"
fi
mkdir -p "$APP_DIR"
cd "$APP_DIR"
ok "Site directory: $APP_DIR"

# ── decode + verify one embedded file ───────────────────────────────
write_file() {  # write_file <relative-path> <sha256> < <b64-gzip on stdin>
  local rel="$1" sum="$2" tmp
  tmp="$(mktemp)"
  base64 -d | gzip -dc > "$tmp"
  if command -v sha256sum >/dev/null 2>&1; then
    echo "${sum}  ${tmp}" | sha256sum -c - >/dev/null 2>&1 \
      || { rm -f "$tmp"; die "Checksum mismatch for ${rel} — the download was corrupted. Download again and retry."; }
  fi
  mkdir -p "$(dirname "$rel")"
  mv "$tmp" "$rel"
  ok "written: $rel"
}

log "Extracting VORTEXNET shop files…"

